import{c as s,Q as e,j as n,m as l}from"./chunks/framework.8JjYC3xy.js";const u=JSON.parse('{"title":"第九章：代码审查和优化","description":"学会让 Claude 做代码审查","frontmatter":{"title":"第九章：代码审查和优化","description":"学会让 Claude 做代码审查"},"headers":[],"relativePath":"guide/3-practical-workflows/09-code-review.md","filePath":"guide/3-practical-workflows/09-code-review.md"}'),p={name:"guide/3-practical-workflows/09-code-review.md"};function i(t,a,o,c,d,h){return e(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="第九章-代码审查和优化" tabindex="-1">第九章：代码审查和优化 <a class="header-anchor" href="#第九章-代码审查和优化" aria-label="Permalink to &quot;第九章：代码审查和优化&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会用 Claude Code 进行高效的代码审查，发现潜在问题并给出优化建议。</p></div><h2 id="为什么-claude-擅长代码审查" tabindex="-1">为什么 Claude 擅长代码审查？ <a class="header-anchor" href="#为什么-claude-擅长代码审查" aria-label="Permalink to &quot;为什么 Claude 擅长代码审查？&quot;">​</a></h2><p>传统代码审查依赖人工 Reviewer，受限于：</p><ul><li>疲劳感 — 看了 50 个 PR 后注意力下降</li><li>上下文切换 — 打断手头工作去 Review</li><li>视角单一 — 一个人难免有盲点</li></ul><p>Claude Code 做代码审查的优势：</p><ul><li>不知疲倦，保持一致的审查标准</li><li>一次性覆盖安全、性能、可读性、逻辑多个维度</li><li>随时可用，不打扰你的工作节奏</li></ul><h2 id="开始代码审查" tabindex="-1">开始代码审查 <a class="header-anchor" href="#开始代码审查" aria-label="Permalink to &quot;开始代码审查&quot;">​</a></h2><h3 id="方法一-斜杠命令-最简单" tabindex="-1">方法一：斜杠命令（最简单） <a class="header-anchor" href="#方法一-斜杠命令-最简单" aria-label="Permalink to &quot;方法一：斜杠命令（最简单）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/review</span></span></code></pre></div><p>Claude 会分析当前分支的所有代码变更，从这几个维度给出建议：</p><ul><li>潜在 bug</li><li>安全风险</li><li>代码可读性</li><li>性能问题</li><li>架构建议</li></ul><h3 id="方法二-指定审查重点" tabindex="-1">方法二：指定审查重点 <a class="header-anchor" href="#方法二-指定审查重点" aria-label="Permalink to &quot;方法二：指定审查重点&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/review</span></span>
<span class="line"><span>重点关注：安全漏洞和潜在的 SQL 注入</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/review</span></span>
<span class="line"><span>重点关注：性能问题，特别是循环和数据库查询</span></span></code></pre></div><h3 id="方法三-直接问具体问题" tabindex="-1">方法三：直接问具体问题 <a class="header-anchor" href="#方法三-直接问具体问题" aria-label="Permalink to &quot;方法三：直接问具体问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个文件有没有安全风险？</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我检查 auth.ts 中的密码处理逻辑是否安全</span></span></code></pre></div><h2 id="按类型分类的审查-prompt" tabindex="-1">按类型分类的审查 Prompt <a class="header-anchor" href="#按类型分类的审查-prompt" aria-label="Permalink to &quot;按类型分类的审查 Prompt&quot;">​</a></h2><h3 id="安全漏洞" tabindex="-1">安全漏洞 <a class="header-anchor" href="#安全漏洞" aria-label="Permalink to &quot;安全漏洞&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>审查这段代码的安全问题：</span></span>
<span class="line"><span>- SQL 注入</span></span>
<span class="line"><span>- XSS 攻击</span></span>
<span class="line"><span>- 密码明文存储</span></span>
<span class="line"><span>- 敏感信息泄露</span></span>
<span class="line"><span>- 不安全的依赖</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【粘贴代码】</span></span></code></pre></div><h3 id="性能问题" tabindex="-1">性能问题 <a class="header-anchor" href="#性能问题" aria-label="Permalink to &quot;性能问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>分析这段代码的性能瓶颈：</span></span>
<span class="line"><span>- 循环效率</span></span>
<span class="line"><span>- 数据库查询（N+1 问题）</span></span>
<span class="line"><span>- 不必要的重复计算</span></span>
<span class="line"><span>- 内存占用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【粘贴代码】</span></span></code></pre></div><h3 id="代码可读性" tabindex="-1">代码可读性 <a class="header-anchor" href="#代码可读性" aria-label="Permalink to &quot;代码可读性&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>审查这段代码的可读性：</span></span>
<span class="line"><span>- 变量命名是否清晰</span></span>
<span class="line"><span>- 函数是否过长</span></span>
<span class="line"><span>- 注释是否充分</span></span>
<span class="line"><span>- 是否有重复代码</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【粘贴代码】</span></span></code></pre></div><h3 id="逻辑错误" tabindex="-1">逻辑错误 <a class="header-anchor" href="#逻辑错误" aria-label="Permalink to &quot;逻辑错误&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>审查这段代码的业务逻辑：</span></span>
<span class="line"><span>- 边界条件是否处理</span></span>
<span class="line"><span>- 异常流程是否覆盖</span></span>
<span class="line"><span>- 状态转换是否正确</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【粘贴代码】</span></span></code></pre></div><h2 id="让-claude-逐个修复" tabindex="-1">让 Claude 逐个修复 <a class="header-anchor" href="#让-claude-逐个修复" aria-label="Permalink to &quot;让 Claude 逐个修复&quot;">​</a></h2><p>不要一次接受所有修改建议。逐个来：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先修复命名问题，其他的先不动</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接下来处理安全漏洞</span></span></code></pre></div><p>这样你可以控制改动范围，每步都可以 Review。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: Claude 说的对不对？</strong></p><p>A: 保持批判思维。Claude 的建议是基于模式识别，不一定理解你的业务逻辑。重要的改动先理解再接受。</p><p><strong>Q: 优化建议太多了？</strong></p><p>A: 正常。先处理高风险问题（安全 &gt; bug &gt; 性能 &gt; 可读性）。用&quot;先修复 X，其他的先不动&quot;来控制范围。</p><p><strong>Q: 可以让 Claude 审查特定文件吗？</strong></p><p>A: 当然。直接说：<code>审查 src/auth/login.ts</code></p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>用 <code>/review</code> 审查你项目中的任意文件</li><li>让 Claude 重点检查安全漏洞</li><li>用分步方式：先问&quot;有没有 SQL 注入风险&quot;，再问&quot;有没有 XSS 风险&quot;</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>下一章我们会学习如何让 Claude 帮你处理 Git 操作。</p><p><a href="/claude-code-guide/guide/3-practical-workflows/10-git-operations.html">👉 第十章：Git 操作辅助</a></p>`,44)])])}const b=s(p,[["render",i]]);export{u as __pageData,b as default};
